questions.example:
temp = int(input("Enter the temperature in Celsius: "))

if temp >= 30:
    print("It's a heatwave! Stay hydrated.")
elif temp >= 20:
    print("Perfect weather for a park visit.")
elif temp >= 10:
    print("A bit chilly, grab a jacket.")
else:
    print("It's freezing! Wear a coat and scarf.")

age = int(input("Please enter your age: "))

if age >= 18:
    print("You can watch 18, 15, and 12 rated movies.")
elif age >= 15:
    print("You can watch 15 and 12 rated movies.")
elif age >= 12:
    print("You can watch 12 rated movies.")
else:
    print("You can only watch U or PG movies.")

guess = input("Enter the secret code word: ")

if guess == "Python":
    print("Access Granted!")
elif guess == "Java":
    print("Wrong language, but close!")
elif guess == "C++":
    print("Too complex for this game!")
else:
    print("Access Denied. Unknown code word.")

day = int(input("Enter a number (1-7): "))

if day > 7:
    print("Invalid input. Too high!")
elif day > 5:
    print("It's the weekend! Time to relax.")
elif day > 0:
    print("It's a school/work day.")
else:
    print("Invalid input. Too low!")
